def with_updated_configuration(self, options=None,
                                   attribute_options=None):
        """
        Returns a context in which this mapping is updated with the given
        options and attribute options.
        """
        if options is None:
            options = {}
        if attribute_options is None:
            attribute_options = {}
        return self.with_configuration(
            self.options.copy().update(options),
            self.attribute_options.copy().update(attribute_options))

